from typing import List

def split_markdown_row(raw_line: str) -> List[str]:
    line = raw_line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]

    cells = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char == "|":
                current.append("|")
            else:
                current.append("\\" + char)
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == "|":
            cells.append("".join(current).strip())
            current = []
        else:
            current.append(char)

    if current or line.endswith("|"):
        cells.append("".join(current).strip())

    return cells
